import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-paz-para-este-tiempo-ii', 'A',
 [dict(t=1233, e=1285, titulo='Paz es unidad, y empieza en la casa', txt='La palabra eirene, que quiere decir paz, probablemente viene de un verbo, eiro, que quiere decir unir. Esto es bien importante. ¿Cuántos quieren tener paz? Tiene que haber unidad. Pues empecemos en la casa. ¿Hay paz en su casa? Porque si no, hoy el Señor la va a desatar. Hoy el Señor va a poner un espíritu de paz en su casa y todo espíritu contrario se tendrá que ir.'),
  dict(t=2652, e=2700, titulo='La paz es fruto del Espíritu', txt='Entonces, ¿qué necesitamos? Unidad. Entonces viene la paz. La paz es un fruto del espíritu; entonces se tiene que manifestar en nosotros. ¿Qué otra cosa dijimos? Prosperidad. Yo lo desato a usted para que sea próspero. […] Hoy le tengo que decir que usted puede ser próspero tanto espiritual como materialmente […]. Yo lo quiero bendecir a usted hoy.'),
  dict(t=4453, e=4498, titulo='En las manos de Dios nadie le hará daño', txt='Que haya paz en su alma, en su espíritu, alma y cuerpo. Reciba, reciba el amor de Dios. Reciba la paz que necesita para que pueda vivir en este mundo donde no hay paz. No hay paz: violencia, muerte. Pero usted está en las manos de Dios. Y si usted está en las manos de Dios, nadie, nadie le va a hacer daño. No se salga de ahí. Pida bendición de parte de Dios.')],
 [dict(t=1612, txt='Este mensaje Dios le está hablando a los que están medio regulares para que se afirmen.'),
  dict(t=2017, txt='Podrás tener la razón, pero tenés que vivir en paz. Deja que Dios obre, que Dios te defienda.'),
  dict(t=4286, txt='Dios nunca, nunca te va a dejar avergonzado.')],
 ['Si la paz nace de la unidad, ¿qué paso puedes dar esta semana para que haya más unidad en tu casa?',
  '¿Qué situación te tienta a defender tu razón en vez de dejar que Dios obre y te defienda?',
  '¿Cómo puedes vivir en paz en medio de un mundo sin paz, permaneciendo en las manos de Dios?'],
 inicio=464)
